import{_ as t,o as r,c as e,a8 as n}from"./chunks/framework.BWjTbCIc.js";const h=JSON.parse('{"title":"汇基书院（东九龙） · 年份未注明 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-c10c51a8","school_zh":"汇基书院（东九龙）","school_en":"—","grade":"s1","year":"unknown","year_label":"年份未注明","type":"interview","title":"汇基书院（东九龙） · 年份未注明 · 中一 · 面试","anonymous":true,"source_ids":["CONF-UCCKE-S1-CHAT","GUIDE-UCCKE","UCCKE-S1-HISTORY-COLLECTION"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/school-c10c51a8/s1/unknown-interview.md","filePath":"reports/school-c10c51a8/s1/unknown-interview.md"}'),s={name:"reports/school-c10c51a8/s1/unknown-interview.md"};function a(p,o,c,l,i,g){return r(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="汇基书院-东九龙-·-年份未注明-·-中一-·-面试" tabindex="-1">汇基书院（东九龙） · 年份未注明 · 中一 · 面试 <a class="header-anchor" href="#汇基书院-东九龙-·-年份未注明-·-中一-·-面试" aria-label="Permalink to &quot;汇基书院（东九龙） · 年份未注明 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-c10c51a8">← 返回汇基书院（东九龙）资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-conf-uccke-s1-chat" tabindex="-1">资料来源：崇真中学&amp;汇基书院中一面经.png <a class="header-anchor" href="#record-conf-uccke-s1-chat" aria-label="Permalink to &quot;资料来源：崇真中学&amp;amp;汇基书院中一面经.png {#record-conf-uccke-s1-chat}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生／家长反馈整理</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>个人面试：</strong> 英语</p><p><strong>家庭、通勤与校园适应</strong></p><p>老师全程用英语提问，内容包括是否想要弟弟妹妹、住在深圳如何通勤，以及如何适应校园生活、结交朋友。</p></blockquote><blockquote><p><strong>小组面试：</strong> 普通话</p><p><strong>全球变暖等话题</strong></p><p>以抢答形式讨论全球变暖等话题。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>回答速度与参与情况</strong></p><p>个人问答的回应速度较慢，但总体能够应答；小组同学发言积极，该生较难抢到机会，经常最后回答。</p></blockquote><h2 id="record-guide-uccke" tabindex="-1">资料来源：滙基書院(東九龍)面試題.pdf <a class="header-anchor" href="#record-guide-uccke" aria-label="Permalink to &quot;资料来源：滙基書院(東九龍)面試題.pdf {#record-guide-uccke}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构整理：历年面试题型</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>个人面谈与小组讨论</strong></p><p>历史整理的整体流程约40至60分钟，包括英文个人面谈及约8人的中文小组讨论。英文个人问答约3题；具体追问会随考生回答展开。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>自我介绍与阅读</strong></p><p>介绍学习情况、兴趣、个人特点、报读原因及未来计划；追问可能涉及为什么喜欢某项活动、为什么阅读、最近读过的书及对阅读的看法。另有朗读文章及回答相关问题。</p><p><strong>简短表达</strong></p><p>例题包括说明选择现就读学校的原因，以及描述一个苹果。</p></blockquote><blockquote><p><strong>语文：</strong> 中文</p><p><strong>共享单车与校园资源</strong></p><p>阅读共享单车主题文章，讨论其优缺点；进一步讨论学校适合共享哪些物品或资源，并说明利弊。每位组员均需发言，可赞同或反对其他观点，并给出理由。</p><p><strong>社会情境与校园设计</strong></p><ul><li>急症室加价是否能有效减少滥用？</li><li>选一则关注或印象深刻的新闻，解释原因并表达对相关政策的看法。</li><li>对小六学生用500元纸币支付车费的行为有什么看法？</li><li>如何看待受欢迎的餐厅加价？</li><li>假如负责学生会活动，如何为学校开放日设计游戏？</li></ul></blockquote><h2 id="record-uccke-s1-history-collection" tabindex="-1">资料来源：汇基书院中一面试.pdf <a class="header-anchor" href="#record-uccke-s1-history-collection" aria-label="Permalink to &quot;资料来源：汇基书院中一面试.pdf {#record-uccke-s1-history-collection}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构整理：历年面试题型</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-2" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-2" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>个人与小组环节</strong></p><p>历史整理的整体流程约40至60分钟，包括英文个人面谈及中文小组讨论；两种任务不视为两次独立到校考试。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读、自我介绍与追问</strong></p><p>即场朗读文章，再回答老师的问题；用约2至3分钟自我介绍，并接受追问。例子包括说明为何选择学校，以及用英文形容一个苹果。</p></blockquote><blockquote><p><strong>语文：</strong> 粤语</p><p><strong>八人小组讨论</strong></p><p>八人一组，共同阅读材料，老师提出约3个问题，每位学生均需作答。历年题目包括：</p><ul><li>共享单车有哪些利弊？学校可共享什么物品，为什么？这样做的好处与坏处是什么？</li><li>为什么推行垃圾收费？怎样减少垃圾？小学有没有垃圾分类，对分类有什么建议？</li><li>如果担任学生会主席，会怎样组织活动？</li><li>急症室收费增加，能否减少滥用？</li></ul></blockquote><blockquote><p><strong>准备参考：</strong></p><p><strong>机构建议</strong></p><p>讨论时表达观点，也应倾听和回应组员；不同意见需说明理由。机构建议不熟悉粤语的考生尽量清楚表达想法，但可否改用其他语言，应按当次学校安排。</p></blockquote>',28)])])}const d=t(s,[["render",a]]);export{h as __pageData,d as default};
